package android.app;import android.content.*;public class PendingIntent {public static final int FLAG_UPDATE_CURRENT=1,FLAG_IMMUTABLE=2,FLAG_NO_CREATE=4;public int id;public Intent intent;public static PendingIntent getBroadcast(Context c,int id,Intent i,int flags){PendingIntent p=new PendingIntent();p.id=id;p.intent=i;return p;}public static PendingIntent getActivity(Context c,int id,Intent i,int flags){if((flags&FLAG_NO_CREATE)!=0)return null;PendingIntent p=new PendingIntent();p.id=id;p.intent=i;return p;}public void cancel(){}}